function run(input) {
    try {
        const raw = String(input || "").replace(/[^a-zA-Z0-9]/g, "");
        let type = null;

        if (raw.length === 11 && /^\d+$/.test(raw)) {
            type = "CPF";
        } else if (raw.length === 14) {
            type = "CNPJ";
        } else {
            return false;
        }

        function isNumeric(str) {
            return /^\d+$/.test(str);
        }

        function validateCpf(cpf) {
            if (!/^\d{11}$/.test(cpf)) return false;
            if (/^(\d)\1+$/.test(cpf)) return false;

            let sum = 0;

            for (let i = 0; i < 9; i++) {
                sum += parseInt(cpf[i]) * (10 - i);
            }

            let rev = 11 - (sum % 11);

            if (rev >= 10) {
                rev = 0;
            }

            if (rev !== parseInt(cpf[9])) {
                return false;
            }

            sum = 0;

            for (let i = 0; i < 10; i++) {
                sum += parseInt(cpf[i]) * (11 - i);
            }

            rev = 11 - (sum % 11);

            if (rev >= 10) {
                rev = 0;
            }

            if (rev !== parseInt(cpf[10])) {
                return false;
            }

            return true;
        }

        function formatCnpj(cnpj) {
            if (/^\d{14}$/.test(cnpj)) {
                return cnpj.replace(
                    /(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,
                    "$1.$2.$3/$4-$5"
                );
            }

            return cnpj.replace(
                /(.{2})(.{3})(.{3})(.{4})(.{2})/,
                "$1.$2.$3/$4-$5"
            );
        }

        function validateCnpj(cnpj) {
            if (!isNumeric(cnpj)) {
                return true;
            }

            if (/^(\d)\1+$/.test(cnpj)) {
                return false;
            }

            let length = cnpj.length - 2;
            let numbers = cnpj.substring(0, length);
            let digits = cnpj.substring(length);
            let sum = 0;
            let pos = length - 7;

            for (let i = length; i >= 1; i--) {
                sum += numbers[length - i] * pos--;
                if (pos < 2) {
                    pos = 9;
                }
            }

            let result = sum % 11 < 2
                ? 0
                : 11 - (sum % 11);

            if (result != digits[0]) {
                return false;
            }

            length++;
            numbers = cnpj.substring(0, length);
            sum = 0;
            pos = length - 7;

            for (let i = length; i >= 1; i--) {
                sum += numbers[length - i] * pos--;
                if (pos < 2) {
                    pos = 9;
                }
            }

            result = sum % 11 < 2
                ? 0
                : 11 - (sum % 11);

            if (result != digits[1]) {
                return false;
            }

            return true;
        }

        const isValid = type === "CPF"
            ? validateCpf(raw)
            : validateCnpj(raw);

        if (!isValid) {
            return false;
        }

        return {
            raw: raw,
            type: type,
            formatted: type === "CPF"
                ? raw.replace(
                    /(\d{3})(\d{3})(\d{3})(\d{2})/,
                    "$1.$2.$3-$4"
                )
                : formatCnpj(raw)
        };

    } catch (e) {
        return false;
    }
}

