function run(horaEntrada, horaFim) {
  try {
    function parseDataGMT0(dataTexto) {
      const [data, hora] = dataTexto.split(" ");
      const [mes, dia, ano] = data.split("/");
      const [hh, mm, ss] = hora.split(":");

      return new Date(Date.UTC(ano, mes - 1, dia, hh, mm, ss));
    }

    function formatarBrasil(data) {
      const dataBrasil = new Date(data.getTime() - 3 * 60 * 60 * 1000);

      const dia = String(dataBrasil.getUTCDate()).padStart(2, "0");
      const mes = String(dataBrasil.getUTCMonth() + 1).padStart(2, "0");
      const ano = dataBrasil.getUTCFullYear();

      const hora = String(dataBrasil.getUTCHours()).padStart(2, "0");
      const minuto = String(dataBrasil.getUTCMinutes()).padStart(2, "0");

      return {
        data: `${dia}/${mes}/${ano}`,
        hora: `${hora}:${minuto}`
      };
    }

    const entrada = parseDataGMT0(horaEntrada);
    const fim = parseDataGMT0(horaFim);

    const diferencaMs = fim - entrada;
    const totalSegundos = Math.floor(diferencaMs / 1000);
    const totalMinutos = Math.floor(totalSegundos / 60);

    const horas = Math.floor(totalMinutos / 60);
    const minutos = totalMinutos % 60;
    const segundos = totalSegundos % 60;

    const entradaFormatada = formatarBrasil(entrada);
    const fimFormatada = formatarBrasil(fim);

    let tempoTexto = "";

    if (horas > 0) {
      tempoTexto += `${horas} ${horas === 1 ? "hora" : "horas"}`;
    }

    if (minutos > 0) {
      if (tempoTexto) tempoTexto += " e ";
      tempoTexto += `${minutos} ${minutos === 1 ? "minuto" : "minutos"}`;
    }

    if (horas === 0 && minutos === 0) {
      tempoTexto = `${segundos} ${segundos === 1 ? "segundo" : "segundos"}`;
    }

    return {
      horaEntrada,
      horaFim,
      tempoInteracao: {
        horas,
        minutos,
        segundos,
        totalMinutos,
        totalSegundos
      },
      relatorio: `Entrou às ${entradaFormatada.hora} do dia ${entradaFormatada.data} finalizou interação às ${fimFormatada.hora} do dia ${fimFormatada.data} tempo de interação de ${tempoTexto}`
    };
  } catch (error) {
    return {
      erro: "Erro ao calcular tempo de interação"
    };
  }
}

function run(input) {
  try {
    const data = typeof input === "string" ? JSON.parse(input) : input;

    // Cliente não existe
    if (
      !data ||
      !data.data ||
      !data.data.get_person_customer ||
      !Array.isArray(data.data.get_person_customer.items) ||
      data.data.get_person_customer.items.length === 0
    ) {
      return false;
    }

    const item = data.data.get_person_customer.items[0];

    // Formata nome:
    // VALDIR ZIMMERMANN KAIST
    // -> Valdir Zimmermann Kaist
    function formatarNome(nome) {
      if (!nome) {
        return null;
      }

      return String(nome)
        .trim()
        .toLowerCase()
        .split(/\s+/)
        .map(function (parte) {
          return parte.charAt(0).toUpperCase() + parte.slice(1);
        })
        .join(" ");
    }

    const shared_id = item.shared_id || null;

    const document_id =
      item.documents &&
      item.documents.length > 0 &&
      item.documents[0].document_id
        ? item.documents[0].document_id
        : null;

    // Nome completo formatado
    const Name = formatarNome(item.description);

    // Primeiro nome
    const FirstName =
      Name
        ? Name.split(/\s+/)[0]
        : null;

    // E-mail
    const Email = item.email
      ? String(item.email).trim()
      : null;

    const salesInfo = Array.isArray(item.sales_informations)
      ? item.sales_informations
      : [];

    // Procura shipping_code com endereço
    for (let i = 0; i < salesInfo.length; i++) {
      const partners = Array.isArray(salesInfo[i].partners)
        ? salesInfo[i].partners
        : [];

      for (let j = 0; j < partners.length; j++) {
        const partner = partners[j];

        if (
          partner &&
          partner.partner_function === "shipping_code" &&
          Array.isArray(partner.addresses) &&
          partner.addresses.length > 0
        ) {
          return {
            shared_id: shared_id,
            document_id: document_id,

            FirstName: FirstName,
            Name: Name,
            Email: Email,

            partner_function: partner.partner_function,
            addresses: partner.addresses[0]
          };
        }
      }
    }

    // Não encontrou shipping_code
    return {
      shared_id: shared_id,
      document_id: document_id,

      FirstName: FirstName,
      Name: Name,
      Email: Email,

      partner_function: "shipping_code",
      addresses: false
    };

  } catch (e) {
    return false;
  }
}

