function run(contactIdentity, contactPhoneNumber, inputMessageMetadata) {
    try {
        let identity = contactIdentity || "";
        let phoneNumber = contactPhoneNumber || "";

        // Extrair apenas a parte antes do '@' da variável identity (Antigo BSUID, agora guid)
        let idPart = identity.split('@')[0];

        // Extração flexível do BSUID (Aceita o JSON inteiro ou apenas o metadado)
        let bsuid = "false";
        if (inputMessageMetadata) {
            try {
                let parsedInput = typeof inputMessageMetadata === "string" 
                    ? JSON.parse(inputMessageMetadata) 
                    : inputMessageMetadata;

                // Cenário 1: Se recebeu o JSON inteiro contendo o objeto .metadata interno
                if (parsedInput && parsedInput.metadata && parsedInput.metadata["#wa.bsuid"]) {
                    bsuid = parsedInput.metadata["#wa.bsuid"];
                } 
                // Cenário 2: Se recebeu diretamente apenas o objeto metadata {}
                else if (parsedInput && parsedInput["#wa.bsuid"]) {
                    bsuid = parsedInput["#wa.bsuid"];
                }
            } catch (e) {
                // Se o parse falhar por string corrompida, bsuid continua "false"
            }
        }

        // Função para garantir o formato +55
        const formatToPlus55 = (numberStr) => {
            let cleanNumber = numberStr.trim().replace(/[^\d+]/g, '');
            if (!cleanNumber) return "";

            if (cleanNumber.startsWith('+55')) {
                return '+' + cleanNumber.replace(/\D/g, '');
            }

            let digitsOnly = cleanNumber.replace(/\D/g, '');

            if (digitsOnly.startsWith('55')) {
                return '+' + digitsOnly;
            }

            return '+55' + digitsOnly;
        };

        const isPhoneValid = (numberStr) => {
            let cleanNumber = numberStr.replace(/\D/g, '');
            return /^\d{10,15}$/.test(cleanNumber);
        };

        // Formata e valida os campos
        let formattedIdPart = formatToPlus55(idPart);
        let isIdentityPhone = isPhoneValid(idPart); 

        let formattedPhoneNumber = formatToPlus55(phoneNumber);
        let isPhoneNumberValid = phoneNumber.trim() !== "" && isPhoneValid(formattedPhoneNumber);

        // Mapeamentos para a nova estrutura de guid
        let guidStatus = isIdentityPhone ? "false" : "true";
        let guid = isIdentityPhone ? "false" : idPart;

        let phoneStatus = "false";
        if (phoneNumber.trim() === "") {
            phoneStatus = "false";
        } else if (isPhoneNumberValid) {
            phoneStatus = "true";
        }

        let finalPhone = "false";
        if (isIdentityPhone) {
            finalPhone = formattedIdPart;
        } else if (isPhoneNumberValid) {
            finalPhone = formattedPhoneNumber;
        }

        // Retorno com guid e o bsuid extraído do metadado
        let result = {
            "guidStatus": guidStatus,
            "guid": guid,
            "bsuid": bsuid,
            "phoneStatus": phoneStatus,
            "phone": finalPhone
        };

        return JSON.stringify(result);

    } catch (error) {
        let errorResult = {
            "guidStatus": "false",
            "guid": "false",
            "bsuid": "false",
            "phoneStatus": "false",
            "phone": "false",
            "error": error.message
        };

        return JSON.stringify(errorResult);
    }
}

function run(number) {
  try {
    if (!number) return false;

    if (number.trim().startsWith('+') && !number.trim().startsWith('+55')) {
        return "+" + number.toString().replace(/[^\d]+/g, "");
    }

    let numberFormatting = number.toString().replace(/[^\d]+/g, "");
    if (numberFormatting.length >= 10) {
      if (numberFormatting.length >= 12 && numberFormatting.startsWith('55')) {
        numberFormatting = numberFormatting.slice(2);
      }
      if (numberFormatting.startsWith('0')) {
        numberFormatting = numberFormatting.slice(1);
      }
      //número completo
      if (numberFormatting.length >= 12) {
        return false
      } else {
        numberFormatting = "55" + numberFormatting;
        return "+" + numberFormatting;
      }
    } else {
      return false
    }
  } catch(e) {
    return false;
  }
}

