      if (!nome) {
        return null;
      }

      return String(nome)
        .trim()
        .toLowerCase()
        .split(/\s+/)
        .map(function (parte) {
          return parte.charAt(0).toUpperCase() + parte.slice(1);
        })
        .join(" ");
    }

    const shared_id = item.shared_id || null;

    const document_id =
      item.documents &&
      item.documents.length > 0 &&
      item.documents[0].document_id
        ? item.documents[0].document_id
        : null;

    // Nome completo formatado
    const Name = formatarNome(item.description);

    // Primeiro nome
    const FirstName =
      Name
        ? Name.split(/\s+/)[0]
        : null;

    // E-mail
    const Email = item.email
      ? String(item.email).trim()
      : null;

    const salesInfo = Array.isArray(item.sales_informations)
      ? item.sales_informations
      : [];

    // Procura shipping_code com endereço
    for (let i = 0; i < salesInfo.length; i++) {
      const partners = Array.isArray(salesInfo[i].partners)
        ? salesInfo[i].partners
        : [];

      for (let j = 0; j < partners.length; j++) {
        const partner = partners[j];

        if (
          partner &&
          partner.partner_function === "shipping_code" &&
          Array.isArray(partner.addresses) &&
          partner.addresses.length > 0
        ) {
          return {
            shared_id: shared_id,
            document_id: document_id,

            FirstName: FirstName,
            Name: Name,
            Email: Email,

            partner_function: partner.partner_function,
            addresses: partner.addresses[0]
          };
        }
      }
    }

    // Não encontrou shipping_code
    return {
      shared_id: shared_id,
      document_id: document_id,

      FirstName: FirstName,
      Name: Name,
      Email: Email,

      partner_function: "shipping_code",
      addresses: false
    };

  } catch (e) {
    return false;
  }
}

