function run(input) {
    try {
        const data = typeof input === "string"
            ? JSON.parse(input)
            : input;

        if (!data) {
            return "";
        }

        function mascararEmail(email) {
            if (!email || typeof email !== "string") {
                return "";
            }

            const emailLimpo = email.trim();

            const emailMatch = emailLimpo.match(
                /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/
            );

            if (!emailMatch) {
                return "";
            }

            const partes = emailLimpo.split("@");

            if (partes.length !== 2) {
                return "";
            }

            const usuario = partes[0];
            const dominio = partes[1];

            const finalUsuario = usuario.length <= 2
                ? usuario
                : usuario.slice(-2);

            return "***" + finalUsuario + "@" + dominio;
        }

        let registros = [];

        if (Array.isArray(data)) {
            registros = data;
        } else if (Array.isArray(data.records)) {
            registros = data.records;
        } else {
            registros = [data];
        }

        const emailsMascarados = [];

        registros.forEach(function (registro) {
            if (!registro || !registro.Email) {
                return;
            }

            const emails = String(registro.Email)
                .split(/[;,]+/)
                .map(function (email) {
                    return email.trim();
                })
                .filter(function (email) {
                    return email !== "";
                });

            emails.forEach(function (email) {
                const emailMascarado = mascararEmail(email);

                if (emailMascarado) {
                    emailsMascarados.push(emailMascarado);
                }
            });
        });

        if (emailsMascarados.length === 0) {
            return "";
        }

        return emailsMascarados.join("\n");

    } catch (e) {
        return "";
    }
}

